src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            # Each nested rectangular band is a uniform color. Reverse the band colors.
            layers=[]
            depth=0
            while r0+depth <= r1-depth and c0+depth <= c1-depth:
                cells=[(y,x) for y,x in comp if min(y-r0,r1-y,x-c0,c1-x)==depth]
                if not cells: break
                colors={grid[y][x] for y,x in cells}
                if len(colors)!=1: break
                layers.append(next(iter(colors)))
                depth+=1
            if len(layers)>1:
                mapping={layers[i]:layers[len(layers)-1-i] for i in range(len(layers))}
                for y,x in comp:
                    if grid[y][x] in mapping: out[y][x]=mapping[grid[y][x]]
    return out
'''
